<?php

namespace Tests\Fixtures;

/**
 * Imagens mínimas para os testes dos slides (Sprint 254), em base64: o
 * ambiente de teste não tem GD para desenhar uma. 40×20 em paisagem, a mesma
 * com EXIF de orientação 6 (de pé, girada 90°), um PNG em retrato e um WEBP —
 * que o PowerPoint não abre.
 */
final class Imagens
{
    public const JPEG = '';

    public const JPEG_EXIF_6 = '';

    public const PNG = 'iVBORw0KGgoAAAANSUhEUgAAABQAAAAeCAIAAACjcKk8AAAAL0lEQVR4nGNkqFZhwAucZ4XhkmLCrxM/GNVMT82MzqJVA2PzqOZRzaOaRzUPZc0A/BoC34QCU/gAAAAASUVORK5CYII=';

    public const WEBP = 'UklGRmgAAABXRUJQVlA4IFwAAAAwAwCdASoUABQAPm0ylUekIqIhKAgAgA2JYwAALnVQp/yIAP7ypAjGTmklafMegcL4X89/o5Ms32wvSv+ypMN/kuyv///FzPff7HJlmi9/Nf4/Nc8fYEH/vgAAAA==';

    /** Grava a imagem num arquivo temporário e devolve o caminho. */
    public static function arquivo(string $base64): string
    {
        $caminho = (string) tempnam(sys_get_temp_dir(), 'img');
        file_put_contents($caminho, base64_decode($base64));

        return $caminho;
    }
}
